\begin{align*}
&\begin{matrix}
\bullet & \bullet & \bullet & \bullet & \bullet 
\bullet & \bullet & \bullet & \bullet & \bullet 
\bullet & \bullet & \bullet & \bullet & \bullet 
\color{blue}{\bullet} & \bullet & \bullet & \bullet & \bullet
