We start by giving a construction. If  $n$  is odd, we can consider any triangulation. If  $n$  is even, denote  $A_1A_2\dots A_n$  as the regular polygon. Consider drawing in all the diagonals that are parallel to  $A_nA_2$ , and all the diagonals perpendicular to  $A_1A_{n/2+1}$ .
[asy]
size(10cm);

real R = 2.0;
pair[] P = new pair[12];

for(int i=0; i<12; ++i){
  P*= R*dir(90 - i*30);
}

for(int i=0; i<12; ++i){
  draw(P[i]--P[(i+1)%12], black+0.8bp);
}

for(int i=0; i<12; ++i){
  string lab = " $A_{"+string(i+1)+"}$ ";
  label(lab, P[i], 1.2*P[i]);
}

pair v1 = P[1] - P[11];
pair v2 = P[6] - P[0];

bool isParallel(pair a, pair b){
  return abs(a.x*b.y - a.y*b.x) < 1e-6;
}

pen p1 = blue + linewidth(1.0);
pen p2 = red  + linewidth(1.0);

for(int i=0; i<12; ++i){
  for(int j=i+1; j<12; ++j){
    pair u = P[j] - P[i];
    if(isParallel(u, v1)){
      draw(P[i]--P[j], p1);
    }
    if(isParallel(u, v2)){
      draw(P[i]--P[j], p2);
    }
  }
